width = 3
height = 3
rounds = 3

universe = [[0 1 0]
            [0 1 0]
            [0 1 0]]

next = height.of({width.of(0)})

cell = { x, y |
  true? x < width && { x >= 0 && { y >= 0 && { y < height }}}
  {
    universe[y][x]
  }
  { 0 }
}

neighbors = { x, y |
  cell(x - 1, y - 1) +
  cell(x, y - 1) +
  cell(x + 1, y - 1) +
  cell(x + 1, y) +
  cell(x + 1, y + 1) +
  cell(x, y + 1) +
  cell(x - 1, y + 1) +
  cell(x - 1, y)
}

set_next = { x, y, v |
  next[y][x] = v
}

step = {
  universe.each_with_index { row, y |
    row.each_with_index { c, x |
      n = neighbors(x, y)

      when { n < 2 } { set_next x,y, 0 }
           { n > 3 } { set_next x, y, 0 }
           { n == 3 } { set_next x, y, 1 }
           { true } { set_next x, y, c }
    }
  }

  u2 = universe
  universe = next
  next = u2
}

display = {
  p universe.map({ r |
    r.map({ n | true? n == 0, '-', "O" }).join
  }).join("\n")
}

rounds.times {
  display
  p
  step
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define for_x for (int x = 0; x < w; x++)
#define for_y for (int y = 0; y < h; y++)
#define for_xy for_x for_y
void show(void *u, int w, int h)
{
   int (*univ)[w] = u;
   printf("\033[H");
   for_y {
      for_x printf(univ[y][x] ? "\033[07m  \033[m" : "  ");
      printf("\033[E");
   }
   fflush(stdout);
}

void evolve(void *u, int w, int h)
{
   unsigned (*univ)[w] = u;
   unsigned new[h][w];

   for_y for_x {
      int n = 0;
      for (int y1 = y - 1; y1 <= y + 1; y1++)
         for (int x1 = x - 1; x1 <= x + 1; x1++)
            if (univ[(y1 + h) % h][(x1 + w) % w])
               n++;

      if (univ[y][x]) n--;
      new[y][x] = (n == 3 || (n == 2 && univ[y][x]));
   }
   for_y for_x univ[y][x] = new[y][x];
}

void game(int w, int h)
{
   unsigned univ[h][w];
   for_xy univ[y][x] = rand() < RAND_MAX / 10 ? 1 : 0;
   while (1) {
      show(univ, w, h);
      evolve(univ, w, h);
      usleep(200000);
   }
}

int main(int c, char **v)
{
