            CrLf(0);
            ];
        CrLf(0);

        for Y:= 1 to M do                       \determine next generation
            for X:= 1 to M do
                [N:= 0;                         \count adjacent live (#) cells
                for J:= Y-1 to Y+1 do
                    for I:= X-1 to X+1 do
                        if NowGen(I,J) = ^# then N:= N+1;
                if NowGen(X,Y) = ^# then N:= N-1;       \don't count center
                NewGen(X,Y):= ^ ;                       \assume death
                if N=2 then NewGen(X,Y):= NowGen(X,Y)   \actually no change
                else if N=3 then NewGen(X,Y):= ^#;      \actually birth
                ];
        I:= NowGen;  NowGen:= NewGen;  NewGen:= I;      \swap arrays
        ];
]

const std = @import("std");
const mem = std.mem;

pub fn main() !void {
    // ---------------------------- pseudo random number generator
    var prng = std.Random.DefaultPrng.init(blk: {
        var seed: u64 = undefined;
        std.posix.getrandom(mem.asBytes(&seed)) catch unreachable;
        break :blk seed;
    });
    const random = prng.random();
    // ----------------------------------------------------------
    const stdout = std.io.getStdOut();
    var bw = std.io.bufferedWriter(stdout.writer());
    const writer = bw.writer();
    // ----------------------------------------------------------
    var life = Life(80, 15).init(random);
    for (0..300) |_| {
        life.step();
        try writer.writeByte('\x0c');
        try writer.print("{}", .{life});
        try bw.flush();
        std.time.sleep(comptime (1_000_000_000 / 30)); // 1/30th second
    }
}
fn Life(comptime w: usize, comptime h: usize) type {
    return struct {
        const Self = @This();
        a: Field(w, h),
        b: Field(w, h),

        fn init(random: std.Random) Self {
            var life = Self{
                .a = Field(w, h).init(),
                .b = Field(w, h).init(),
            };
            for (0..w * h / 2) |_| {
                const x = random.uintLessThan(usize, w);
                const y = random.uintLessThan(usize, h);
                life.a.set(x, y, true);
            }
            return life;
        }
        fn step(self: *Self) void {
            for (0..h) |y|
                for (0..w) |x|
                    self.b.set(x, y, self.a.next(x, y));
            mem.swap(Field(w, h), &self.a, &self.b);
        }
        pub fn format(self: *const Self, comptime _: []const u8, _: std.fmt.FormatOptions, writer: anytype) !void {
            for (0..h) |y| {
                for (0..w) |x|
                    try writer.writeByte(if (self.a.state(x, y)) '*' else ' ');
                try writer.writeByte('\n');
            }
        }
    };
}
fn Field(comptime w: usize, comptime h: usize) type {
    return struct {
        const Self = @This();
        s: std.StaticBitSet(w * h),

        fn init() Self {
            return .{ .s = std.StaticBitSet(w * h).initEmpty() };
        }
        fn set(self: *Self, x: usize, y: usize, b: bool) void {
            self.s.setValue(y * w + x, b);
        }
        fn next(self: *const Self, x_: usize, y_: usize) bool {
            var on: usize = 0;
            // Use wraparound arithmetic, i.e. -%
            inline for ([3]usize{ x_ -% 1, x_, x_ + 1 }) |x|
                inline for ([3]usize{ y_ -% 1, y_, y_ + 1 }) |y|
                    if (self.state(x, y)) {
                        on += 1;
                    };
            return on == 3 or on == 2 and self.state(x_, y_);
        }
        fn state(self: *const Self, x: usize, y: usize) bool {
            if (x >= w or y >= h) return false;
            return self.s.isSet(y * w + x);
        }
    };
}

class Life{
   fcn init(n, r1,c1, r2,c2, etc){
      var N=n, cells=Data(n*n), tmp=Data(n*n),
        ds=T(T(-1,-1),T(-1,0),T(-1,1), T(0,-1),T(0,1), T(1,-1),T(1,0),T(1,1));
      icells:=vm.arglist[1,*];
      (N*N).pump(Void,cells.append.fpM("1-",0));   // clear board
      icells.pump(Void,Void.Read,fcn(row,col){ cells[row*N+col]=1 });
   }
   fcn get(row,col){
      if((0<=row<N) and (0<=col<N)) return(cells[row*N+col]);
      return(0);
   }
   fcn postToastie(row,col){
      n:=ds.reduce('wrap(n,[(r,c)]){n+get(r+row,c+col)},0);
      c:=get(row,col);
      ((n==2 and c==1) or n==3).toInt()
   }
   fcn cycle{
      tmp.clear();
      foreach row in (N){ foreach col in (N) {
         tmp.append(postToastie(row,col)) } }
      t:=cells; cells=tmp; tmp=t;
   }
   fcn toString{
      cells.pump(0,String,fcn(c,rn){
         (if(c)"*" else "-") + (if(rn.inc()%N) "" else "\n")
      }.fp1(Ref(1)));
   }
   fcn toAnsi{
      cells.pump(0,"\e[H",fcn(c,rn){
         (if(c)"\e[07m  \e[m" else "  ") + (if(rn.inc()%N) "" else "\e[E")
      }.fp1(Ref(1)));
   }
   fcn dance(n=300){ do(n){ toAnsi().print(); Atomic.sleep(0.2); cycle(); } }
}

